const DEFAULT_MODEL = "@cf/meta/llama-3.1-8b-instruct";
const MAX_PROMPT_CHARS = 500;
const MAX_HISTORY = 10;
const MAX_DETAIL_CHUNKS = 4;
const RATE_LIMIT = { windowMs: 60_000, max: 20 };      // per visitor IP, per worker instance (best effort)

/* ---------------------------------------------------------------------
   Retrieval: always send the core knowledge, plus the detail chunks that
   best match the visitor's question (full case studies, blog posts, ...).
   --------------------------------------------------------------------- */
const STOP = new Set("the a an and or of to in on for with is are was were be been it its this that these those you your yours he his him she her they them we our us i me my do does did can could would should will what which who whom how why when where about tell more any some please give show want need like have has had get just also than then so if at by from as not no yes ok okay hi hello hey".split(" "));

function tokens(text) {
  return String(text || "").toLowerCase().replace(/[^a-z0-9+#.\s-]/g, " ").split(/\s+/)
    .map((w) => w.replace(/^[-.]+|[-.]+$/g, "")).filter((w) => w.length > 2 && !STOP.has(w))
    .map((w) => (w.length > 4 && w.endsWith("s") ? w.slice(0, -1) : w));
}

const CHUNK_INDEX = CHUNKS.map((c) => ({ c, key: new Set(tokens(c.keys)), body: new Set(tokens(c.text)) }));

function pickChunks(query) {
  const q = [...new Set(tokens(query))];
  const scored = [];
  for (const { c, key, body } of CHUNK_INDEX) {
    if (c.always) continue;
    let s = 0;
    for (const w of q) { if (key.has(w)) s += 3; else if (body.has(w)) s += 1; }
    if (s >= 2) scored.push({ c, s });
  }
  scored.sort((a, b) => b.s - a.s);
  const core = CHUNK_INDEX.filter((x) => x.c.always).map((x) => x.c.text);
  const detail = scored.slice(0, MAX_DETAIL_CHUNKS).map((x) => x.c.text);
  return core.concat(detail).join("\n\n");
}

/* ---------------------------------------------------------------------
   Sales / closing detection (deterministic, so it works even when the
   model forgets the [[WHATSAPP]] marker).
   --------------------------------------------------------------------- */
const SALES = /\b(hire|hiring|freelanc\w*|contract|quote|quotation|pric\w*|cost|budget|rates?|charges?|how much|estimate|proposal|need (?:a|an|someone|help)|looking for|want (?:a|an|to (?:build|make|create|develop))|build (?:me|a|an|us|my)|develop (?:a|an|my)|(?:create|make) (?:a|an|my)|(?:our|my) (?:company|startup|business|app|website|project|idea|product)|work with|collaborat\w*|enquir\w*|inquir\w*|available|availability|timeline|how long|deadline)\b/i;
const CLOSING = /^\W*(?:ok(?:ay)?|thanks?|thank you|thx|great|cool|nice|got it|perfect|sounds good|that'?s all|that is all|bye|goodbye|see you|done|alright|fine|will do|sure)\b[\s\S]{0,30}$/i;
const WANTS_CONTACT = /\b(whatsapp|call (?:him|you)|talk to (?:him|you|bineesh)|speak (?:to|with)|get started|let'?s (?:start|go|talk|do it)|proceed|book (?:a|the)? ?(?:call|meeting|consultation)|schedule)\b/i;

function whatsappUrl(userMessages) {
  const need = userMessages.find((m) => SALES.test(m));
  const summary = need ? need.replace(/\s+/g, " ").slice(0, 180) : "";
  const text = "Hi Bineesh, I was chatting with your portfolio assistant." +
    (summary ? ` I wanted to discuss: "${summary}"` : " I'd like to discuss a project.");
  return `https://wa.me/${CONFIG.whatsappNumber}?text=${encodeURIComponent(text)}`;
}

/* ---------------------------------------------------------------------
   HTTP helpers
   --------------------------------------------------------------------- */
function corsHeaders(request, env) {
  const allowed = String(env.ALLOWED_ORIGINS || "*").split(",").map((s) => s.trim()).filter(Boolean);
  const origin = request.headers.get("Origin") || "";
  const allow = allowed.includes("*") ? "*" : allowed.includes(origin) ? origin : allowed[0];
  return {
    "Access-Control-Allow-Origin": allow,
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin",
  };
}

function json(body, status, headers) {
  return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", ...headers } });
}

const hits = new Map();
function limited(ip) {
  const now = Date.now();
  const list = (hits.get(ip) || []).filter((t) => now - t < RATE_LIMIT.windowMs);
  list.push(now);
  hits.set(ip, list);
  if (hits.size > 5000) hits.clear();
  return list.length > RATE_LIMIT.max;
}

function cleanTurns(list) {
  return (Array.isArray(list) ? list : [])
    .filter((m) => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim())
    .map((m) => ({ role: m.role, content: m.content.trim().slice(0, 1500) }));
}

/* ---------------------------------------------------------------------
   Worker
   --------------------------------------------------------------------- */
export default {
  async fetch(request, env) {
    const cors = corsHeaders(request, env);

    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (request.method === "GET") return json({ ok: true, ai: !!env.AI, model: env.MODEL || DEFAULT_MODEL }, 200, cors);   // open the worker URL in a browser to check it is alive
    if (request.method !== "POST") return json({ error: "Send a POST request" }, 405, cors);
    if (!env.AI) return json({ error: "Cloudflare 'AI' binding is not configured" }, 500, cors);

    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    if (limited(ip)) return json({ error: "Too many messages, please wait a moment" }, 429, cors);

    let body;
    try { body = await request.json(); } catch { return json({ error: "Invalid JSON" }, 400, cors); }

    /* conversation = (messages | history + prompt), system messages from clients are ignored */
    let turns;
    if (Array.isArray(body.messages) && body.messages.length) {
      turns = cleanTurns(body.messages);
    } else {
      turns = cleanTurns(body.history);
      const prompt = String(body.prompt || "").trim();
      if (prompt) turns.push({ role: "user", content: prompt });
    }
    turns = turns.slice(-MAX_HISTORY);
    if (!turns.length || turns[turns.length - 1].role !== "user") return json({ error: "Missing prompt" }, 400, cors);
    turns[turns.length - 1].content = turns[turns.length - 1].content.slice(0, MAX_PROMPT_CHARS);

    const userMsgs = turns.filter((t) => t.role === "user").map((t) => t.content);
    const latest = userMsgs[userMsgs.length - 1];

    /* knowledge for this question (current + previous user message give context for follow-ups) */
    const knowledge = pickChunks(userMsgs.slice(-2).join(" "));
    const system = SYSTEM_PROMPT.replace("{{KNOWLEDGE}}", knowledge);

    try {
      const out = await env.AI.run(env.MODEL || DEFAULT_MODEL, {
        messages: [{ role: "system", content: system }, ...turns],
        max_tokens: 420,
        temperature: 0.35,
      });

      const raw = out && (out.response || (out.result && out.result.response) || (out.choices && out.choices[0] && out.choices[0].message && out.choices[0].message.content));
      let text = String(raw || "").trim();
      if (!text) return json({ error: "Empty model response" }, 502, cors);

      /* the model asks for the WhatsApp button with a marker; we also add it on our own at natural end points */
      const marker = /\[\[\s*whatsapp\s*\]\]/i;
      let wants = marker.test(text);
      text = text.replace(/\[\[\s*whatsapp\s*\]\]/gi, "").replace(/\n{3,}/g, "\n\n").trim();

      const enquiry = userMsgs.some((m) => SALES.test(m));
      if (!wants) {
        if (WANTS_CONTACT.test(latest)) wants = true;
        else if (CLOSING.test(latest) && latest.length <= 40 && turns.length >= 3) wants = true;
        else if (enquiry && userMsgs.length >= 4) wants = true;                       // a real enquiry that is going on: offer the next step
      }

      const reply = { response: text };
      if (wants) reply.whatsapp = whatsappUrl(userMsgs);
      return json(reply, 200, cors);
    } catch (err) {
      return json({ error: "AI request failed", detail: String((err && err.message) || err).slice(0, 300) }, 502, cors);
    }
  },
};
